# aeneid-083 (XI.100-224): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Indutiae. Luctus Evandri'
PART = "The Truce, Evander's Lament and the Pyres (XI.100–224)"
TITLE_EN = "The Truce, Evander's Lament and the Pyres — Aeneid XI.100–224"
ABOUT = ("Envoys come from King Latinus's city with olive branches to ask for the bodies of their dead. "
"Aeneas grants it readily and more: he never wished to fight the Latins, he says; their king broke faith with him and trusted himself to Turnus, and Turnus, not these men, ought to have settled the war hand to hand with him. "
"Drances, an old enemy of Turnus, answers with lavish praise and promises to work for peace between Aeneas and Latinus. "
"A truce of twelve days is agreed, and Trojans and Latins go together into the woods to cut timber for the pyres. "
"Meanwhile Rumour has brought the news to Pallanteum. The Arcadians come out with torches to meet the funeral train, and old Evander throws himself on his son's body and speaks his lament: Pallas had promised to be careful; better that the father had died in the war; he blames neither the Trojans nor the alliance; and he charges Aeneas with one last duty, to repay Turnus for his son. "
"At dawn the Trojans and Etruscans burn their dead on the shore with the old rites, and the Latins burn theirs, while in Latinus's city the mourning women curse the war and Turnus's marriage. "
"Drances stirs the anger against Turnus, but the queen's favour and his own fame still stand by him. "
"The truce for burying the dead has its model in Book 7 of the Iliad.")

U = [
(101, 'rogantes:',
 """And now envoys were present from the city Latin,\nveiled with branches of olive, and favour asking:""",
 """And now envoys had arrived from the Latin city, wreathed in olive branches and asking for grace:""",
 """A new paragraph in Greenough. 'oratores', 'spokesmen, envoys', from 'oro', 'speak, plead'. 'urbe Latina', the city of King Latinus. 'velati', 'veiled, wreathed', perfect participle: the olive branch wound with wool was the sign of a suppliant, as in Evander's welcome of the Trojans (VIII.116). 'veniam', 'favour, indulgence', a grace asked of one who need not give it. The colon opens what they asked. The embassy asking a truce to bury the dead has its model in the Iliad, where the Trojans send to the Greeks for the same purpose (Iliad 7). Elision 'Iamqu(e) oratores'."""),
(103, 'terrae;',
 """the bodies, over the plains by the sword which strewn were lying,\nhe should give back and to the mound let them go beneath, of earth;""",
 """that he would give back the bodies that lay strewn over the plain, cut down by the sword, and let them go beneath a mound of earth;""",
 """Their request in indirect speech: 'redderet… sineret', imperfect subjunctives standing for the imperatives of the envoys' words ('give back… allow'), after the idea of asking in 'rogantes'. 'corpora' is put first, ahead of its relative clause 'quae… iacebant'. 'fusa', 'poured out, strewn', from 'fundo'. 'tumulo… succedere terrae', 'to go under the mound of earth', burial; 'tumulo' is dative with the compound verb. No elisions."""),
(104, 'cassis;',
 """no contest with the beaten and with those of the upper air deprived;""",
 """there could be no quarrel, they said, with the defeated and with men bereft of the light of day;""",
 """Still the envoys' words, now an indirect statement with 'esse' left out: '(there was) no contest with the conquered'. 'aethere cassis', 'deprived of the upper air', the dead: 'cassus' takes the ablative of what is lacking, and 'aether' is the bright air the living breathe. One is not at war with the dead, a principle of Greek and Roman custom alike. No elisions."""),
(105, 'vocatis.',
 """he should spare those once as hosts and fathers-in-law called.""",
 """let him spare men he had once called his hosts and his kin by marriage.""",
 """'parceret', the last of the requests, with the dative 'hospitibus… socerisque'. 'hospitibus', 'hosts', Latinus received the Trojans as guests and friends in Book VII. 'soceris', 'fathers-in-law': Latinus offered Aeneas his daughter Lavinia, and the plural spreads the tie over the whole people. 'quondam', 'once', before the war broke the bond. No elisions."""),
(107, 'addit:',
 """Them good Aeneas, not to be spurned asking,\nattends with favour, and words these besides he adds:""",
 """Good Aeneas granted them the grace they asked, which was not one to refuse, and added these words besides:""",
 """'Quos', a connecting relative, 'and them'. 'haud aspernanda precantis', 'asking things not to be spurned', 'aspernanda' a gerundive in the neuter plural and 'precantis' an accusative plural in '-is' agreeing with 'quos'. 'prosequitur venia', 'follows them up with favour', grants their request. 'bonus Aeneas', 'good', where the poem usually says 'pius'. 'insuper', 'over and above', more than they asked. Elision 'veni(a) et'."""),
(109, 'amicos?',
 """“What, you, so great, fortune unworthy, Latins,\nhas entangled in a war, that us you should flee, friends?""",
 """“What undeserved misfortune, Latins, has entangled you in so great a war, that you should shun us, who are your friends?""",
 """Aeneas's answer, which runs to 119. 'Quaenam… fortuna indigna', 'what unworthy fortune', one you did not deserve. 'tanto… bello', ablative with 'implicuit', 'has entangled in so great a war', the words framing the question. 'qui… fugiatis', 'that you flee', a relative clause of result with the subjunctive: 'qui' = 'ut vos'. 'amicos', in apposition to 'nos', 'us, your friends'. Elision 'fortun(a) indigna'."""),
(111, 'oratis?',
 """Peace of me for the lifeless and by Mars's lot destroyed\ndo you beg?""",
 """You ask me for peace for the dead, for men cut off by the chances of war?""",
 """'Pacem me… oratis', 'do you beg me for peace', 'oro' with two accusatives, the person asked and the thing asked for. 'exanimis… peremptis', datives, 'for the lifeless… for those destroyed'. 'Martis sorte', 'by the lot of Mars', the chance of battle, Mars standing for war as often. The question is a gentle reproach: so little to ask. Elision 'm(e) exanimis'."""),
(111, 'vellem.',
 """Indeed even to the living to grant I would wish.""",
 """For my part I would gladly grant it to the living too.""",
 """'Equidem', 'I for my part', strengthening the statement. 'et vivis', 'to the living also', 'et' meaning 'even'. 'vellem', imperfect subjunctive of 'volo', 'I would wish', a wish that the present does not allow: the living are still at war with him. 'concedere', 'to grant', with peace understood. Elision 'Equid(em) et'."""),
(113, 'gero:',
 """Nor would I have come, had not the fates a place and settlement given,\nnor war with the people do I wage:""",
 """I should not have come here at all, had the fates not granted me a place and a home, and it is not with your people that I make war:""",
 """'Nec veni, nisi… dedissent', 'I would not have come, if the fates had not given', a condition contrary to fact with the indicative 'veni' in the main clause for vividness: he came only because fate sent him. 'locum sedemque', 'a place and a settled home', the promised land of Italy. 'cum gente', 'with your race', the Latin people as against their leaders. No elisions."""),
(114, 'armis.',
 """the king ours has abandoned\nhospitality, and to Turnus's rather himself has trusted arms.""",
 """it is your king who has forsaken our bond of friendship and preferred to trust himself to the arms of Turnus.""",
 """'rex', Latinus. 'nostra… hospitia', 'our hospitality', the guest-friendship between him and the Trojans, poetic plural; the words frame the line-end. 'reliquit', 'has left, abandoned'. In Book VII Latinus welcomed the embassy and offered his daughter, then let the war happen when Juno and Allecto stirred his people up. 'potius', 'rather'. 'se credidit armis', 'trusted himself to the arms'. Elision 'hospiti(a) et'."""),
(115, 'morti.',
 """Fairer to this Turnus had been himself to oppose death.""",
 """It would have been fairer for Turnus to stand up to this death himself.""",
 """'Aequius… fuerat', 'it would have been fairer', the pluperfect indicative where English uses 'would have': with words of fitness, duty and possibility Latin often keeps the indicative in such a statement. 'huic… morti', dative with 'se opponere', 'to set himself against this death', the deaths these envoys are mourning. 'Turnum', subject of the infinitive. Elision 's(e) opponere'."""),
(117, 'telis:',
 """If war to end by hand, if to drive out the Teucrians\nhe is preparing, with these with me it was fitting to have met, weapons:""",
 """If he means to end the war by force and drive out the Trojans, he ought to have met me with these weapons:""",
 """'Si… apparat', 'if he is preparing', a simple present condition: Turnus is still at it. 'manu', 'by hand', by fighting. 'Teucros', the Trojans, named from Teucer, an early king of Troy. 'decuit concurrere', 'it was fitting to run together (with me)', to meet me in single combat: the perfect 'decuit' says what he should have done already. 'his… telis', 'with these weapons', which Aeneas holds, framing the second half of the line. No elisions."""),
(118, 'dedisset.',
 """he would have lived, to whom life god or his own right hand had given.""",
 """and that man would have lived to whom a god or his own right hand had given life.""",
 """'vixet', Greenough's 'vixet', a syncopated form of 'vixisset', 'he would have lived', an old form Virgil keeps once here: the pluperfect subjunctive of an unreal past condition. The subject is the relative clause: 'he would have lived to whom god or his own right hand had granted life', that is, whichever of the two had won. 'dedisset', subjunctive by attraction into the conditional sentence. A single combat would have settled everything and spared these dead. No elisions."""),
(119, 'ignem.”',
 """Now go, and to the wretched set beneath, to your citizens, fire.”""",
 """Now go, and light the fires beneath your unhappy countrymen.”""",
 """'ite… supponite', imperatives: Aeneas grants the request. 'supponite… ignem', 'put fire beneath', light the pyres on which the dead lie. 'miseris… civibus', dative with the compound verb, framing the line. The speech ends. Elision 'it(e) et'."""),
(120, 'Aeneas.',
 """Had spoken Aeneas.""",
 """Aeneas had spoken.""",
 """'Dixerat', pluperfect, 'he had spoken', the regular epic formula for the end of a speech (you'll see it constantly); the pluperfect closes off the speech before the reaction begins. No elisions."""),
(121, 'tenebant.',
 """They were stunned, silent,\nand turned, their eyes on each other and faces kept.""",
 """They stood amazed and silent, and kept their eyes and faces turned upon one another.""",
 """'Illi', the envoys. 'obstipuere', the '-ere' ending for '-erunt', 'they were struck dumb': they had expected to be refused or bargained with, not to be met with generosity. 'conversi oculos… atque ora', 'turned as to their eyes and faces', a passive participle used like a Greek middle, with the accusative of the part (as 'crinem… solutae' in XI.35); 'tenebant' goes with it, 'they kept (them) turned'. 'inter se', 'on one another'. Elisions 'Ill(i) obstipuere', 'conversiqu(e) oculos', 's(e) atque', 'atqu(e) ora'."""),
(124, 'refert:',
 """Then the elder, and always with hatreds and accusation, Drances,\nhostile to the young Turnus, thus with his mouth in turn\nwords begun returns:""",
 """Then Drances, an older man, who had always hated the young Turnus and spoken against him, answered in his turn with these words:""",
 """Drances appears here for the first time; he will speak against Turnus again in the council later in this book. 'senior', 'the elder', set against 'iuveni Turno': it is the quarrel of an old talker with a young fighter. 'odiis et crimine', 'with hatreds and accusation', ablatives of manner with 'infensus', 'hostile'. 'sic ore… orsa refert', 'thus returns with his mouth the words he began', a heavy epic way to say 'he replies': 'orsa', neuter plural of 'orsus' from 'ordior', 'what one has begun', words. 'vicissim', 'in turn'. Elision 'semperqu(e) odiis'."""),
(125, 'aequem?',
 """“O in fame great, greater in arms,\nman of Troy, with what to the sky you praises shall I make equal?""",
 """“Man of Troy, great in fame and greater still in arms, with what praises can I raise you as high as heaven?""",
 """Drances's speech, which runs to 131. 'fama ingens, ingentior armis', 'huge in fame, huger in arms', ablatives of respect, with the same word repeated in another form (polyptoton): flattery from the first words. 'vir Troiane', vocative. 'quibus… laudibus', 'with what praises', the words framing the half-line. 'caelo… aequem', 'should I make (you) equal to the sky', exalt you to heaven; 'aequem' is a deliberative subjunctive, 'what am I to do'. Elision 'fam(a) ingens'."""),
(126, 'laborum?',
 """Your justice first shall I admire, or of war the labours?""",
 """Shall I marvel first at your justice or at your toils in war?""",
 """'-ne… -ne', a double question, 'whether… or': 'Iustitiaene… belline'. The genitives 'iustitiae' and 'laborum' go with 'mirer', 'should I wonder at', a genitive of cause after a verb of feeling, a Greek construction. 'mirer', deliberative subjunctive again. The two praises answer Aeneas's mercy and Aeneas's challenge. No elisions."""),
(129, 'regi:',
 """We indeed these things to the native, grateful, will carry back, to the city,\nand you, if any way gives fortune, to Latinus\nwe will join, the king:""",
 """We for our part will gratefully carry these words back to our native city, and, if fortune gives us any way to do it, we will make you King Latinus's ally:""",
 """'Nos vero', 'we for our part', emphatic. 'haec', 'these things', Aeneas's words and his offer. 'patriam… ad urbem', 'to our native city', framing the line. 'grati', nominative plural, 'grateful', with 'nos'. 'siqua', Greenough's one-word spelling of 'si qua', 'if in any way', with 'viam… fortuna', 'if fortune shall have given any way'; 'dederit' is future perfect. 'Latino… regi', dative with 'iungemus', 'we will join (you) to King Latinus', in friendship and marriage. Elision 'ver(o) haec'."""),
(129, 'Turnus.',
 """let seek for himself treaties Turnus.""",
 """Turnus can find himself allies of his own.""",
 """'quaerat', jussive subjunctive, 'let him seek'. 'sibi', 'for himself', on his own account: Drances would leave Turnus to make his own alliances, a contemptuous dismissal. 'foedera', 'treaties, alliances'. 'Turnus' held to the end for scorn. No elisions."""),
(131, 'iuvabit.”',
 """Nay, even the fated of walls to raise up masses\nand stones to carry up on shoulders Trojan will be a pleasure.”""",
 """Indeed, we shall be glad even to raise the destined walls of your great city and to carry its stones on our shoulders.”""",
 """'Quin et', 'nay even', going one better. 'fatalis… moles', 'the fated masses', the great walls of the city fate has promised Aeneas; 'fatalis' is an accusative plural in '-is'. 'murorum', genitive, 'of walls'. 'subvectare', 'to carry up', a frequentative of 'subveho'. 'saxa… Troiana', 'Trojan stones', the stones of the new Troy, framing the line. 'iuvabit', 'it will please (us)'. The speech ends. Elisions 'muror(um) attollere', 'subvectar(e) umeris'."""),
(132, 'fremebant.',
 """Had spoken these things, and with one all the same with mouth were murmuring.""",
 """So he spoke, and all of them murmured the same assent with one voice.""",
 """'Dixerat haec', the formula again, with 'haec'. 'uno… ore', 'with one mouth', with one voice, the words framing 'omnes eadem'. 'eadem', neuter plural, 'the same things'. 'fremebant', 'were murmuring, roaring', here of agreement: the verb is used of any crowd sound, angry or approving. Elisions 'unoqu(e) omnes', 'ead(em) ore'."""),
(135, 'iugis.',
 """Twice six they agreed days, and with peace as go-between\nthrough the woods the Teucrians and, mingled, without harm the Latins\nwandered over the ridges.""",
 """They agreed on twelve days, and with the truce standing between them Trojans and Latins wandered together unharmed through the woods on the hills.""",
 """'Bis senos… dies', 'twice six days', the distributive numeral, a twelve-day truce. 'pepigere', '-ere' for '-erunt', perfect of 'pango', 'agreed, settled'. 'pace sequestra', ablative absolute, 'peace being go-between': a 'sequester' is a trustee who holds something in dispute for both sides, and the truce keeps the two peoples apart while it lets them mix. 'mixti', 'mingled'. 'inpune', Greenough's spelling of 'impune', 'without harm'. 'erravere', '-ere' again. 'iugis', 'on the ridges', ablative of place. Elision 'mixtiqu(e) inpune'."""),
(138, 'ornos.',
 """With iron resounds, the high, double-axe,\nthe ash, they overturn, raised to the stars, the pines,\noaks with wedges and the fragrant to split cedar\nnor with wagons do they cease to carry, groaning, ash-trees.""",
 """The tall ash rings under the iron of the double axe; they bring down pines that had reached to the stars, and they never stop splitting oak and fragrant cedar with wedges, or carting rowans on groaning wagons.""",
 """The timber for the pyres. 'Ferro… bipenni', 'with the double-headed iron', the two-bladed axe, framing the line-end. 'alta… fraxinus', 'the tall ash'. 'actas ad sidera', 'driven up to the stars', grown to a great height. 'nec… cessant… nec', 'they do not cease… nor', with two infinitives, 'scindere', 'to split', and 'vectare', 'to carry', a frequentative. 'olentem… cedrum', 'sweet-smelling cedar'. 'gementibus', 'groaning', of the wagons under the weight. 'ornos', the manna ash or rowan. Compare the woodcutting for Misenus in Book VI (VI.179–182) and for Patroclus's pyre in the Iliad (Iliad 23). No elisions."""),
(141, 'ferebat.',
 """And now Rumour flying, of so great a forerunner grief,\nEvander and Evander's house and walls fills,\nwhich just now as victor in Latium Pallas was carrying.""",
 """And now Rumour, flying ahead to herald so great a sorrow, fills Evander's ears, and Evander's house and town, Rumour that only a little while ago was spreading word of Pallas victorious in Latium.""",
 """A new paragraph in Greenough. 'Fama', Rumour, personified as a winged goddess, whom Virgil describes at length in Book IV. 'praenuntia', 'forerunner', with the genitive 'tanti… luctus', 'of such great grief'. 'Evandrum Evandrique', the name repeated in two cases, to dwell on the father. 'moenia', the walls of Pallanteum, Evander's town. 'quae modo', 'which just now', Rumour again. 'Pallanta', Greek accusative of 'Pallas', with 'victorem', 'carrying (news of) Pallas as victor'. Elision 'Evandr(um) Evandrique'."""),
(143, 'faces;',
 """The Arcadians to the gates rushed, and by custom ancient\nfuneral seized torches;""",
 """The Arcadians rushed to the gates and, following their ancient custom, snatched up funeral torches;""",
 """'Arcades', the Arcadians, Evander's people, Greek settlers in Italy. 'ruere', the historic infinitive, 'they rushed', used for quick action in narrative as if it were a perfect. 'de more vetusto', 'according to ancient custom'. 'funereas… faces', 'funeral torches', framing the half-line: Roman funerals were held by torchlight, at least in early times. 'rapuere', '-ere' again. Elision 'ruer(e) et'."""),
(144, 'agros.',
 """shines the road with a long\nline of flames, and widely marks off the fields.""",
 """the road shone with a long line of flames that marked out the fields far and wide.""",
 """'lucet via', 'the road shines'. 'longo / ordine flammarum', 'with a long line of flames', ablative of means, running over the line-end like the procession itself. 'late discriminat agros', 'divides the fields far and wide': the line of torches cuts through the dark countryside. A picture seen from far off. Elision 'flammar(um) et'."""),
(146, 'agmina.',
 """From the other side, the throng of Phrygians, coming, mourning joins\ncolumns.""",
 """From the other way the Trojan company, coming on, joined their mourning ranks to theirs.""",
 """'Contra', adverb, 'opposite', from the other direction. 'turba Phrygum', 'the throng of Phrygians', the Trojans and their escort of a thousand with the bier (XI.60–63); 'Phrygum' is genitive plural. 'plangentia… agmina', 'beating (their breasts) columns', the mourning procession; 'plango' is to beat the breast in grief. 'iungit', 'joins', with the Arcadians; 'agmina' is held over into the next line. No elisions."""),
(147, 'urbem.',
 """Whom after the mothers to come up to the houses\nsaw, the grieving they set on fire with shrieks, city.""",
 """When the mothers saw them approach the houses, they set the mourning city ablaze with their cries.""",
 """'Quae postquam', 'and after (they saw) these', a connecting relative, 'quae' standing for 'agmina'. 'matres', the women of Pallanteum. 'succedere tectis', 'to come up to the houses', dative with the compound verb. 'maestam… urbem', framing the clause. 'incendunt clamoribus', 'set on fire with shouts', a bold metaphor from the torches: the cries spread through the town like flame. Elision 'maest(am) incendunt'."""),
(149, 'medios.',
 """But not Evander is able any force to hold back,\nbut he comes into the midst.""",
 """But no force could hold Evander back; he went right into the midst of them.""",
 """'potis est', an old form of 'potest', 'is able': 'potis' is an adjective, 'able', used with 'est'. 'vis ulla', 'any force', any attempt to keep the old man away. 'in medios', 'into the midst' of the crowd. 'venit', present, of the action as it happens. No elisions."""),
(151, 'est.',
 """The bier, Pallas, set down,\nhe fell forward over, and clings, both weeping and groaning,\nand a way scarcely at last of the voice was loosed by grief.""",
 """When the bier was set down he threw himself on Pallas and clung to him, weeping and groaning, and it was only with difficulty, at last, that grief left a way open for his voice.""",
 """As printed, 'Feretro Pallanta reposto' is 'the bier having been set down… Pallas', with 'super' as a preposition after its object: 'he fell forward over Pallas'. The Latin Library and many editors read 'Pallante reposto', 'Pallas having been laid on the bier'; the sense is the same and Greenough's reading is kept. 'reposto', syncopated for 'reposito'. 'lacrimansque gemensque', the double '-que'. 'via… vocis', 'the way of the voice', loosed 'dolore', 'by grief', which had choked it. Elision 'atqu(e) haeret'; prodelision 'dolore (e)st'."""),
(153, 'Marti;',
 """“Not these, O Pallas, you had given, the promises, to your father,\nthat more cautiously you would wish to cruel to trust yourself Mars;""",
 """“These were not the promises you gave your father, Pallas, that you would take care in trusting yourself to cruel war;""",
 """Evander's lament, which runs to 181. It opens with the same words as Aeneas's lament over the body ('Non haec… promissa', XI.45), but where Aeneas spoke of his own promises, the father speaks of his son's. 'O Palla', vocative; 'Palla' is the Greek vocative of 'Pallas'. 'dederas', pluperfect. 'ut… velles', 'that you would be willing', a clause explaining the promises. 'cautius', comparative adverb, 'more carefully' (than you did). 'Marti', 'to Mars', to war. No elisions."""),
(155, 'posset.',
 """not unknowing was I how much new glory in arms\nand the very sweet honour in a first contest could do.""",
 """yet I knew well how strong is the pull of fresh glory in arms, and how sweet the honour of a first battle.""",
 """'haud ignarus eram', 'I was not unaware', litotes: he knew the danger and let him go. 'quantum… posset', an indirect question, 'how much (they) could do'. 'nova gloria', 'new glory', the glory a young man wins for the first time. 'praedulce', 'very sweet', 'prae-' strengthening the adjective. 'primo certamine', 'in a first contest', ablative. Elision 'glori(a) in'."""),
(158, 'meae!',
 """First-fruits of the young man wretched, and of war close at hand\nhard first-lessons, and to none heard of the gods\nvows and prayers of mine!""",
 """O the sad first-fruits of his youth, and the harsh schooling in a war so near at hand, and my vows and prayers that no god would hear!""",
 """Exclamations without a verb, as in Aeneas's lament (XI.54–55). 'Primitiae', 'first-fruits', the first offering of a crop: Pallas's first battle was all his harvest. 'iuvenis', genitive, with 'miserae'. 'rudimenta', 'first lessons', a soldier's training; 'dura', 'hard', because it killed him. 'belli… propinqui', 'of a war close at hand', fought near home. 'nulli exaudita deorum', 'heard by none of the gods', 'nulli' dative of the agent with the participle. 'vota precesque', 'vows and prayers'. Elisions 'rudiment(a) et', 'null(i) exaudita'."""),
(159, 'dolorem!',
 """And you, O most holy wife,\nhappy in your death and not for this kept grief!""",
 """And you, my most revered wife, blessed in your death, and not kept alive to suffer this sorrow!""",
 """Evander turns to his dead wife, Pallas's mother, not named in the poem: an apostrophe. 'sanctissima coniunx', 'most holy wife', 'sanctus' of a wife's virtue and the reverence due to the dead. 'felix morte tua', 'fortunate in your death', ablative of cause: she died in time. 'servata', 'preserved', with 'in hunc… dolorem', 'for this grief', framing the half-line. Elisions 'Tuqu(e) O', 'nequ(e) in'."""),
(161, 'genitor.',
 """I on the other hand by living have conquered my fates, surviving\nso that I should remain as a father.""",
 """But I have outlived my destiny, living on, only to be left behind, a father who has survived his son.""",
 """'Contra', 'on the other hand', against the wife's good fortune. 'vivendo', ablative of the gerund, 'by living'. 'vici mea fata', 'I have overcome my fates', lived past the span that should have been mine. 'superstes / restarem ut genitor', 'so that I should be left as a surviving father', a purpose clause stated bitterly as if it were the aim of his long life; 'superstes', 'surviving', is put before 'ut'. Elisions 'Contr(a) ego', 'restar(em) ut'."""),
(162, 'telis!',
 """The Trojans' allied arms following,\nwould that had overwhelmed me the Rutulians with weapons!""",
 """Would that the Rutulians had overwhelmed me with their spears, when I followed the allied arms of Troy!""",
 """A wish without 'utinam': 'obruerent', imperfect subjunctive, 'would that they had buried (me)', a wish that can no longer come true. 'secutum', 'having followed', with 'me' understood, the old man himself marching beside the Trojans. 'Troum', genitive plural of 'Tros', 'of the Trojans', in two syllables. 'Rutuli', Turnus's people. Elision 'soci(a) arma'."""),
(165, 'dextras:',
 """My life I myself would have given,\nand this procession home me, not Pallas, would be bringing back.\nNor would I blame you, Teucrians, nor the treaties, nor which\nwe joined in friendship, right hands:""",
 """I would have given up my own life, and this procession would be carrying me home, not Pallas. And yet I would not blame you, Trojans, nor our treaties, nor the hands we joined in friendship:""",
 """'Animam… dedissem', pluperfect subjunctive, 'I would have given my life', an unreal past. 'referret', imperfect subjunctive, 'would be bringing back (now)', the unreal present: 'domum me, non Pallanta', the bitter exchange of father and son. 'arguerim', perfect subjunctive, potential, 'I would not blame', even so. 'nec… nec… nec', the three things he will not blame. 'quas… dextras', 'the right hands which', the antecedent drawn into the relative clause: the handshake of alliance (VIII.169). 'hospitio', 'in guest-friendship'. Elisions 'Anim(am) ipse', 'atqu(e) haec'."""),
(166, 'nostrae.',
 """this lot to old age\nwas owed, ours.""",
 """this fate was a debt my old age had to pay.""",
 """'sors ista', 'that lot', the death of his son. 'senectae… nostrae', 'to our (my) old age', dative with 'debita erat', 'was due', the words framing the clause and split over the line-end. 'nostrae', the plural of modesty or of feeling, 'my'. Evander takes the blame on himself: it was his fate, not anyone's fault. Elision 'debit(a) erat'."""),
(168, 'iuvabit.',
 """But if untimely was awaiting\ndeath my son, slain the Volscians thousands first,\nleading into Latium the Teucrians to have fallen will be a joy.""",
 """But if an early death was waiting for my son, it will be my comfort that he fell leading the Trojans into Latium, after he had first cut down Volscians by the thousand.""",
 """'Quod si', 'but if', 'quod' only joining the sentence to what went before. 'immatura… mors', 'unripe death', death before its time. 'manebat', 'was awaiting', with the accusative 'natum'. 'caesis… milibus', ablative absolute, 'thousands having been slain', an old man's proud exaggeration. 'Volscorum', the Volsci, a people of Latium, here perhaps standing for the enemy at large. 'ducentem', 'as he led', agreeing with the subject of 'cecidisse', Pallas. 'iuvabit', 'it will please (me)', 'it will be a consolation'. Elisions 's(i) immatura', 'ducent(em) in'."""),
(171, 'omnis.]',
 """Nay, I not with another would deem you worthy funeral, Pallas,\n[than dutiful Aeneas and than the great Phrygians and than]\n[the Tyrrhenian leaders, of the Tyrrhenians the army all.]""",
 """No, I could not think you worthy of any other funeral, Pallas, [than the one dutiful Aeneas and the great Phrygians and the Etruscan chiefs and the whole Etruscan army give you.]""",
 """Greenough prints 170–171 in square brackets as spurious, and they are kept in brackets. With them, 'non alio… quam' is 'with no other funeral than (that which) Aeneas… and the whole army (give you)', and they are the subject of 'ferunt' in 172; without them, 'alio' means 'than this one' and 'ferunt' has no expressed subject. 'Quin', 'nay rather'. 'digner', potential subjunctive of the deponent 'dignor', 'I would deem worthy', with the ablative 'funere'. 'Tyrrheni', the Etruscans; 'Tyrrhenum', genitive plural in '-um'. Elision 'Tyrrhen(um) exercitus'."""),
(172, 'Leto:',
 """Great trophies they carry, of those whom gives your right hand to Death:""",
 """They bring great trophies taken from the men your right hand sent down to Death:""",
 """'Magna tropaea', 'great trophies', the trunks dressed in the enemy's armour carried in the procession (XI.83–84). 'ferunt', 'they carry'. 'quos dat… Leto', 'whom your right hand gives to Death': the antecedent of 'quos' is left out, 'trophies (of those) whom'. 'Leto', dative of 'Letum', Death personified. 'tua dextera', Pallas's right hand, now addressed again. 'dat', present, as if the killing still went on. No elisions."""),
(175, 'Turne.',
 """you too now would be standing, a huge trunk, in arms,\nwere equal his age and the same if strength from the years,\nTurnus.""",
 """you too, Turnus, would be standing now, a huge trunk hung with armour, if my son had been your equal in age and had the strength that the years bring.""",
 """Evander turns to address Turnus, absent: an apostrophe, the name held back to the end. 'stares', imperfect subjunctive, 'you would be standing', an unreal present: Turnus would be a trophy too. 'immanis truncus', 'a huge trunk', the trophy; 'in armis', 'in arms', dressed in your armour. The Latin Library reads 'in arvis', 'in the fields'; Greenough's reading is kept. 'esset… si', 'if there were', the 'si' put late. 'par aetas', 'equal age': Pallas was very young and Turnus a grown warrior. 'ab annis', 'from the years', the strength that comes with age. No elisions."""),
(175, 'armis?',
 """But unhappy, the Teucrians why do I hold back from arms?""",
 """But why, in my misery, do I keep the Trojans from the fighting?""",
 """'Sed', breaking off. 'infelix', nominative, 'I, unhappy', with 'demoror'. 'quid', 'why'. 'demoror… armis', 'do I delay… from arms', 'armis' an ablative of separation: the escort must go back to the war. He turns from lament to the message he will send. No elisions."""),
(176, 'referte:',
 """Go and these, mindful, to the king, instructions carry back:""",
 """Go, and remember to take this message back to your king:""",
 """'Vadite', 'go', a forceful word for setting out. 'memores', 'mindful', nominative plural agreeing with the subject of the imperative: 'carry back and do not forget'. 'regi', 'to the king', Aeneas, now king of the Trojans and the Etruscan alliance. 'haec… mandata', 'these instructions', framing the half-line. The colon opens the message. Elision 'Vadit(e) et'."""),
(179, 'vides.',
 """that I linger in life hateful, Pallas destroyed,\nthe right hand the cause yours is, Turnus to son and father\nwhich owing you see.""",
 """If I drag out a life that I hate now that Pallas is dead, your right hand is the reason, which, as you see, owes Turnus to a son and to a father.""",
 """The message is addressed to Aeneas. 'quod… moror', 'the fact that I linger (in)', a 'quod' clause as subject: 'vitam moror', 'I delay life', I live on. 'invisam', 'hateful'. 'Pallante perempto', ablative absolute. 'dextera… tua', 'your right hand', Aeneas's: he lives only to see it act. 'quam debere vides', 'which you see owes', with 'Turnum' its object: Aeneas's hand owes Turnus's death to the son and the father. Prodelision 'tua (e)st'."""),
(180, 'locus.',
 """For your merits there is open here, for you, only\nand fortune's place.""",
 """This is the one field left for your merits and your fortune.""",
 """'vacat', 'is empty, is free'. 'hic… solus… locus', 'this sole place', the only room left: everything else Aeneas could do for Pallas has been done. 'Meritis… fortunaeque', datives, 'for your deserts and your fortune', what your goodness and your good luck can still achieve. 'tibi', 'for you', dative. No elisions."""),
(181, 'imos.”',
 """Not of life the joys do I seek,\nnor is it right, but for my son to the shades to carry them down, beneath, deepest.”""",
 """It is not for joys in life that I ask, for that would not be right; it is to carry them down to my son among the shades below.”""",
 """'Non vitae gaudia quaero', 'I do not seek joys for my life', from the revenge. 'nec fas', '(nor would it be) right', the verb left out: an old man in mourning should not seek pleasure. 'sed… perferre', 'but to carry (them) through', the 'gaudia' understood as object: he wants to take the news of Turnus's death to Pallas in the underworld. 'nato', dative, 'to my son'. 'Manis… sub imos', 'beneath the lowest shades', 'Manis' an accusative plural in '-is', the spirits of the dead. The speech ends. No elisions."""),
(183, 'labores:',
 """Aurora meanwhile to wretched mortals the kindly\nhad brought out light, bringing back works and labours:""",
 """Meanwhile the Dawn had brought out her kindly light for unhappy mortals, bringing back with it work and toil:""",
 """A new paragraph in Greenough, and back to the Trojan camp. 'Aurora', the Dawn. 'miseris mortalibus', dative, 'for wretched mortals', a phrase with the ring of Homer's 'wretched mortals'. 'almam… lucem', 'nurturing light', framing the clause over the line-end. 'extulerat', pluperfect, 'had raised'. 'referens opera atque labores', 'bringing back works and toils', the day's labour, here the sad work of the funerals. Elisions 'Auror(a) interea', 'oper(a) atque'."""),
(185, 'pyras.',
 """already father Aeneas, already on the curved shore Tarchon\nset up the pyres.""",
 """Aeneas, the father of his people, and Tarchon had already set up pyres on the curving shore.""",
 """'iam… iam', 'already… already', the repetition stressing their promptness. 'pater Aeneas', 'father Aeneas', the title of the leader who cares for his people. 'Tarchon', the Etruscan commander, Aeneas's ally since Book VIII. 'curvo in litore', 'on the curved shore', where the Trojan ships lie. 'constituere', '-ere' for '-erunt'. Elision 'curv(o) in'."""),
(187, 'caelum.',
 """Here bodies each one of his own\nby custom brought of the fathers, and, set beneath the fires black,\nis hidden in shadows the high, by smoke, sky.""",
 """Each man brought the bodies of his own people there according to the custom of his fathers, and when the black fires were lit beneath them the high sky was shrouded in darkness by the smoke.""",
 """'Huc', 'hither', to the pyres. 'corpora… suorum', 'the bodies of his own (men)'. 'quisque', 'each', with the plural verb 'tulere' ('-ere' for '-erunt'), as often. 'more… patrum', 'by the custom of their fathers', each people with its own rites. 'subiectis… ignibus atris', ablative absolute, 'black fires having been placed beneath', black with smoke. 'conditur in tenebras', 'is buried in darkness'. 'caligine', 'by the murk', ablative of means. Elision 'subiectisqu(e) ignibus'."""),
(190, 'dedere;',
 """Three times around the lit, girt with gleaming arms,\nthey ran, the pyres, three times the grieving of the funeral fire\nthey circled on horses, and wailings from their mouths gave;""",
 """Three times they ran round the burning pyres, girt in gleaming armour; three times they rode round the mournful fire of the dead on horseback, and raised loud cries of lamentation;""",
 """The 'decursio', the solemn march or ride round the pyre, a Roman funeral honour for soldiers. 'Ter', 'three times', a sacred number, repeated. 'accensos… rogos', 'the kindled pyres', framing the first part. 'cincti', 'girded', with 'fulgentibus armis'. 'decurrere', 'lustravere', 'dedere', '-ere' for '-erunt'. 'lustravere', 'circled', the word of a purifying procession. 'ululatus', accusative plural, 'howls, wailing'. So the Myrmidons drive three times round Patroclus in the Iliad (Iliad 23.13). Elisions 'circ(um) accensos', 'lustraver(e) in', 'ululatusqu(e) ore'."""),
(191, 'arma:',
 """is sprinkled both the earth with tears, are sprinkled both the arms:""",
 """the ground is wet with tears, and wet the armour too:""",
 """'spargitur… sparguntur', 'is sprinkled… are sprinkled', the verb repeated at the head of each half (anaphora). 'et… et', 'both… and', here 'and… too'. 'lacrimis', 'with tears', serves both halves. The line follows Homer closely: in the Iliad, at the mourning for Patroclus, the sands and the men's armour are wet with tears (Iliad 23.15). No elisions."""),
(192, 'tubarum.',
 """goes to the sky both the shouting of men and the blare of trumpets.""",
 """the shouting of men and the blare of trumpets go up to the sky.""",
 """'it caelo', 'goes to the sky', 'caelo' a poetic dative of the goal of motion. 'clamorque virum clangorque tubarum', 'both the shout of men and the clang of trumpets', the double '-que' and the matching sounds 'clamor… clangor'. 'virum', the old genitive plural in '-um' for 'virorum'. The second half-line is the same as in the sack of Troy (II.313). No elisions."""),
(195, 'rotas;',
 """Here others spoils from the slain stripped Latins\nthrow on the fire, helmets and swords fine\nand bridles and glowing wheels;""",
 """Here some threw on the fire spoils stripped from the Latin dead, helmets and handsome swords, bridles and wheels that had glowed with speed;""",
 """'Hic alii… pars', 'here some… others', the crowd divided. 'spolia… derepta', 'spoils torn off', with the dative 'occisis… Latinis', 'from the slain Latins'. 'coniciunt igni', 'throw onto the fire', 'igni' a dative or an old ablative. 'decoros', 'handsome'. 'ferventis… rotas', 'glowing wheels', hot from the speed of the chariots; 'ferventis' is an accusative plural in '-is'. Spoils were burned as offerings to the dead. Elision 'spoli(a) occisis'."""),
(196, 'tela.',
 """part the gifts known,\nof the men themselves the shields and the not lucky weapons.""",
 """others the gifts the dead had known, their own shields and the weapons that had not brought them luck.""",
 """'pars', 'some', with 'coniciunt' understood: the second group throws in the dead men's own things. 'munera nota', 'familiar gifts', things the dead knew and used. 'ipsorum', 'of the men themselves', the Trojan dead. 'clipeos', 'shields'. 'non felicia tela', 'weapons that were not fortunate', litotes, since they did not save their owners. No elisions."""),
(199, 'pecudes.',
 """Many of oxen around are slaughtered bodies to Death,\nand bristly swine and, seized from all the fields,\ninto the flame they cut the throats of, the cattle.""",
 """Many oxen are slaughtered round about as offerings to Death, and they cut the throats of bristling swine and of flocks gathered from every field over the flames.""",
 """'Multa boum… corpora', 'many bodies of oxen', a stately way of saying 'many oxen'; 'boum' is the genitive plural of 'bos'. 'circa', adverb, 'around'. 'Morti', dative, to Death personified, as 'Leto' at 172. 'saetigeros… sues', 'bristle-bearing swine'. 'raptas… pecudes', 'cattle snatched (from all the fields)', the words framing their phrase. 'iugulant', 'cut the throat', from 'iugulum'. 'in flammam', 'into the flame', the victims falling on the pyres. Elision 'raptasqu(e) ex'."""),
(202, 'aptum.',
 """Then on the shore whole\nburning they watch their comrades, and the half-burnt they guard\npyres, nor to be torn away are they able, night dewy until\nturns over the sky with stars burning fitted.""",
 """Then all along the shore they watched their comrades burn and kept guard over the half-burnt pyres, and could not tear themselves away until dewy night turned round the heavens, set thick with blazing stars.""",
 """'litore toto', 'on the whole shore', ablative of place without a preposition. 'ardentis… socios', 'their comrades burning', 'ardentis' an accusative plural in '-is'. 'semusta… busta', 'the half-burnt pyres', 'semusta' for 'semiusta'; 'bustum' is the place where a body is burned. 'avelli', present passive infinitive, 'to be torn away'. 'donec', 'until', put late. 'invertit caelum', 'turns the sky over', as the heavens rotate and night rises. 'stellis… aptum', 'fitted with stars', studded. Elision 'nequ(e) avelli'."""),
(204, 'pyras,',
 """No less also the wretched, in a different part, Latins\ncountless built pyres,""",
 """No less did the unhappy Latins, in another place, build countless pyres,""",
 """A new paragraph in Greenough: the Latins' funerals, set beside the Trojans'. 'Nec minus et', 'no less also'. 'miseri… Latini', framing the line. 'diversa in parte', 'in a different quarter', away from the Trojan camp. 'innumeras… pyras', 'countless pyres', the Latin dead far outnumbering the Trojans'. 'struxere', '-ere' for '-erunt', perfect of 'struo', 'built'. The comma ends this unit because the sentence runs to 208. Elision 'divers(a) in'."""),
(208, 'cremant:',
 """and bodies, some\nmany of men in the earth bury, and, carried off, some\nto neighbouring they lift, to the fields, and to the city send back,\nthe rest and of confused a huge slaughter heap\nneither with number nor with honour they burn:""",
 """and the many bodies of their men they partly buried in the earth, partly carried away to the neighbouring countryside and sent back to the town, and the rest, a vast heap of tangled slaughter, they burned without count or honour:""",
 """'corpora… multa virum', 'the many bodies of men', 'virum' genitive plural in '-um'. 'partim… partim', 'partly… partly'. 'terrae infodiunt', 'dig into the earth', bury; 'terrae' dative. 'avecta', 'carried away', with 'tollunt in agros', 'lift (onto carts and take) into the fields'. 'urbi… remittunt', 'send back to the city', 'urbi' dative. 'cetera… acervum', 'the rest and (that is) the huge heap', the '-que' explaining 'cetera'. 'confusae… caedis', 'of tangled slaughter'. 'nec numero nec honore', 'without counting and without honour', ablatives of manner. Elisions 'terr(ae) infodiunt', 'confusaequ(e) ingentem'."""),
(209, 'agri.',
 """then on every side the vast\nvying with frequent shine fires the fields.""",
 """then on every side the broad fields blazed, one against another, with fire after fire.""",
 """'tunc undique', 'then on every side'. 'vasti… agri', 'the vast fields', framing the clause. 'certatim', 'in rivalry', as if the fields were competing in light. 'crebris… ignibus', 'with thick-set fires', ablative of means. 'conlucent', Greenough's spelling of 'collucent', 'shine all together'. No elisions."""),
(210, 'umbram:',
 """The third light the cold from the sky had removed shadow:""",
 """The third dawn had driven the chill shadow from the sky:""",
 """'Tertia lux', 'the third light', the third day after the battle. 'gelidam… umbram', 'the cold shadow', night, framing the line round 'caelo dimoverat', 'had moved away from the sky'; 'caelo' is an ablative of separation. The bodies have burned for two days. The colon leads into what the mourners do on the third. No elisions."""),
(212, 'terrae.',
 """grieving, the deep ash and the confused they raked out,\nbones, from the hearths, and with a warm loaded them, a mound of earth.""",
 """in their grief they raked out the deep ashes and the mingled bones from the burning-places and heaped over them a mound of still warm earth.""",
 """'maerentes', 'mourning', the Latins. 'ruebant', 'were raking out', 'ruo' used transitively, 'cast up, rake together'. 'altum cinerem', 'the deep ash'. 'confusa… ossa', 'mingled bones', the bodies burned together beyond telling apart, framing the line-end. 'focis', 'from the hearths', the places of burning; ablative of separation. 'tepido… aggere terrae', 'with a warm mound of earth', warm from the fires below. 'onerabant', 'loaded', covered over. Elisions 'ciner(em) et', 'tepidoqu(e) onerabant'."""),
(214, 'luctus.',
 """But now in the houses, in the city of very rich Latinus,\nthe chief clamour and of the long the greatest part of grief.""",
 """But it was in the homes in the city of wealthy Latinus that the loudest lament was heard, and there the greater part of the long mourning was spent.""",
 """'Iam vero', 'but now', moving to a new scene. 'in tectis… urbe', 'in the houses… in the city', with the verb ('was') left out. 'praedivitis… Latini', 'of very rich Latinus', 'prae-' strengthening the adjective, as 'praedulce' at 155. 'praecipuus fragor', 'the chief uproar', the noise of mourning. 'longi… luctus', 'of the long grief', framing 'pars maxima'. Elision 'ver(o) in'."""),
(217, 'hymenaeos:',
 """Here mothers and wretched brides, here the dear of sisters\nhearts, grieving, and boys of parents bereft\nthe dire curse war, and Turnus's wedding:""",
 """Here mothers and unhappy young wives, here the loving hearts of grieving sisters, and boys robbed of their fathers, cursed the dreadful war and Turnus's marriage:""",
 """'Hic… hic', 'here… here', anaphora, listing the mourners. 'nurus', 'daughters-in-law', young wives whose husbands have fallen. 'cara sororum / pectora maerentum', 'the dear breasts of mourning sisters', a poetic way of saying 'the loving sisters'. 'parentibus orbi', 'bereft of parents', 'orbus' with the ablative of separation. 'exsecrantur', 'curse', deponent. 'Turni… hymenaeos', 'Turnus's wedding', the marriage with Lavinia that the war is being fought for; 'hymenaeus' is a Greek word, from Hymen, god of marriage. Elisions 'dir(um) exsecrantur', 'Turniqu(e) hymenaeos'."""),
(219, 'honores.',
 """him himself with arms, and himself they bid to decide with the sword,\nwho the kingdom of Italy and the first for himself demands, honours.""",
 """they demanded that he himself should settle it in arms, he himself with the sword, since it was he who claimed the throne of Italy and the highest honours for himself.""",
 """'ipsum… ipsumque', 'him himself… himself', Turnus, the word repeated with scorn: let him fight his own war. 'iubent decernere', 'bid (him) decide', 'iubeo' with the infinitive. 'armis… ferro', 'with arms… with the sword', two phrases for one. 'qui… poscat', 'who demands', the subjunctive giving the mourners' reason, 'since he is the one who'. 'primos… honores', 'the first honours', the highest rank. Elisions 'ips(um) armis', 'Itali(ae) et'."""),
(221, 'Turnum.',
 """Makes heavier these things fierce Drances, and alone to be called\nbears witness, alone to be demanded for the combat Turnus.""",
 """Fierce Drances made it all weigh heavier, declaring that Turnus alone was being called, Turnus alone challenged to the fight.""",
 """The print has 'ingravat' with a small letter after the full stop at 219, a misprint for 'Ingravat', corrected here. 'ingravat haec', 'makes these things heavier', adds weight to the mourners' complaints. 'saevus Drances', 'fierce' in his hatred, as at 122–123. 'testatur', 'calls to witness, declares', with two indirect statements, 'solum vocari… solum posci… Turnum', 'that Turnus alone is called… alone demanded': Aeneas has challenged Turnus and no one else (115–118). 'in certamina', 'to the combat'. Elision 'posc(i) in'."""),
(224, 'tropaeis.',
 """Many at the same time on the other side, in various words, an opinion\nfor Turnus, and the great of the queen name shelters him,\nmany a fame of the man supports him with earned trophies.""",
 """At the same time many voices were raised in his favour, with arguments of many kinds; the great name of the queen sheltered him, and his own renown and the trophies he had won held him up.""",
 """'Multa… sententia', 'many an opinion', singular for plural, with the verb left out: '(is spoken) for Turnus'. 'contra', 'on the other side', against Drances. 'variis… dictis', 'with various sayings'. 'reginae nomen', 'the queen's name', Queen Amata, who wanted Turnus for Lavinia; 'obumbrat', 'shadows', shields him. 'multa… fama', 'much renown', framing the last line. 'virum', here the accusative singular, 'the man', Turnus, object of 'sustentat', 'supports'. 'meritis… tropaeis', 'with earned trophies', those he has won. Elision 'Turn(o) et'."""),
]

# Speech-mark check: Greenough's marks in this part are regular (no stray or joined marks), so no exemptions.
EXEMPT = set()
P = A.part('aeneid-083'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
    nw = len(n.split())
    if nw > 139 or nw < 15: print('NOTE LENGTH', ln, nw)
    for mk in '“”[]':
        if t.count(mk) != l.count(mk) and ln not in EXEMPT: print('MARK l', ln, mk)
        if mk in '“”' and t.count(mk) != i.count(mk) and ln not in EXEMPT: print('MARK i', ln, mk)
covered = sorted({ln + k for (t, ln) in cuts for k in range(t.count('\n') + 1)})
if covered != [l['n'] for l in L]: print('COVERAGE', covered)
joined = '\n'.join(l['t'] for l in L)
rebuilt = ''.join(t + ('\n' if (k + 1 < len(cuts) and cuts[k + 1][1] != ln + t.count('\n')) else ' ' if k + 1 < len(cuts) else '') for k, (t, ln) in enumerate(cuts))
if rebuilt != joined: print('JOIN MISMATCH')
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units;', len(covered), 'lines covered')
